SELECT 'batch_024_5b59c9ae_wav_09' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-57aa6388-1d3','sm-upload-702be9dc-d25','sm-upload-87176740-d8e','sm-upload-8f24fa72-b29','sm-upload-b908a83a-97a','sm-upload-be0b96c2-963','sm-upload-d0a56a7b-4f8','sm-upload-de754d56-ea4','sm-upload-fcb9b5ca-27c') AND album_id='al-e8c944eb0c92b7c25aef28645b59c9ae') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-57aa6388-1d3','sm-upload-702be9dc-d25','sm-upload-87176740-d8e','sm-upload-8f24fa72-b29','sm-upload-b908a83a-97a','sm-upload-be0b96c2-963','sm-upload-d0a56a7b-4f8','sm-upload-de754d56-ea4','sm-upload-fcb9b5ca-27c') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-e8c944eb0c92b7c25aef28645b59c9ae' AND name='OTOME') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-e8c944eb0c92b7c25aef28645b59c9ae') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-e8c944eb0c92b7c25aef28645b59c9ae') AS calculated_size;
